package com.brainserve.onboarding.reminders.infrastructure.persistence;import com.brainserve.onboarding.reminders.domain.model.*;import jakarta.persistence.LockModeType;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface ScheduledReminderRepository extends JpaRepository<ScheduledReminder,UUID>{Optional<ScheduledReminder> findByOrganizationIdAndStepIdAndReminderPolicyId(UUID org,UUID stepId,UUID policyId);Optional<ScheduledReminder> findByOrganizationIdAndStepId(UUID org,UUID stepId);Page<ScheduledReminder> findAllByOrganizationId(UUID org,Pageable p);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select r from ScheduledReminder r where r.organizationId=:org and r.id=:id")Optional<ScheduledReminder> findForUpdate(@Param("org")UUID org,@Param("id")UUID id);}
